package com.example.shortener.domain;

import java.time.Instant;

/** Single source of truth for expiry semantics, shared by the entity, the cache entry and the service. */
public final class Expiry {

    private Expiry() {
    }

    /** A link is expired from its expiry instant onwards (inclusive). Links without an expiry never expire. */
    public static boolean isExpired(Instant expiresAt, Instant now) {
        return expiresAt != null && !now.isBefore(expiresAt);
    }
}

