package com.example.shortener.service;

import com.example.shortener.domain.Expiry;
import com.example.shortener.domain.LinkStatus;
import com.example.shortener.domain.ShortUrl;

import java.time.Instant;

/** Immutable, cache-friendly view of a link: only what the redirect path needs. */
public record CachedLink(long id, String longUrl, LinkStatus status, Instant expiresAt) {

    public static CachedLink from(ShortUrl link) {
        return new CachedLink(link.getId(), link.getLongUrl(), link.getStatus(), link.getExpiresAt());
    }

    /** Expiry is re-evaluated on every redirect, so a cached entry can never outlive its expiry. */
    public boolean isExpired(Instant now) {
        return Expiry.isExpired(expiresAt, now);
    }
}

