package com.example.shortener.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

import java.time.Instant;

/**
 * Bean Validation does the cheap shape checks here. The semantic rules (scheme, host, SSRF, alias namespace,
 * expiry in the future) live in the service layer, so they also apply to callers that don't go through HTTP.
 */
public record CreateUrlRequest(
        @NotBlank @Size(max = 2048) String longUrl,
        @Size(min = 3, max = 64) String customAlias,
        Instant expiresAt) {

    /** Backwards-compatible constructor: no expiry. */
    public CreateUrlRequest(String longUrl, String customAlias) {
        this(longUrl, customAlias, null);
    }

    /** Treats a blank alias as "no alias". */
    public String normalizedAlias() {
        return customAlias == null || customAlias.isBlank() ? null : customAlias.trim();
    }
}

package com.example.shortener.api.dto;

import com.example.shortener.domain.ShortUrl;

import java.time.Instant;

public record CreateUrlResponse(String shortCode, String shortUrl, String longUrl, Instant createdAt, Instant expiresAt) {

    public static CreateUrlResponse from(ShortUrl link, String baseUrl) {
        return new CreateUrlResponse(link.getShortCode(), baseUrl + "/" + link.getShortCode(),
                link.getLongUrl(), link.getCreatedAt(), link.getExpiresAt());
    }
}

package com.example.shortener.api.dto;

import com.example.shortener.domain.LinkStatus;
import com.example.shortener.domain.ShortUrl;

import java.time.Instant;

public record UrlDetailsResponse(String shortCode, String shortUrl, String longUrl, LinkStatus status,
                                 boolean customAlias, Instant createdAt, Instant expiresAt) {

    public static UrlDetailsResponse from(ShortUrl link, String baseUrl) {
        return new UrlDetailsResponse(link.getShortCode(), baseUrl + "/" + link.getShortCode(), link.getLongUrl(),
                link.getStatus(), link.isCustomAlias(), link.getCreatedAt(), link.getExpiresAt());
    }
}
